```javascript
const AWS = require('aws-sdk');
const tf = require('tensorflow');

// 📌 Load the model once, not on every invocation
let model;

// 📌 Lazy load the model on first invocation
async function loadModel() {
  if (model) {
    return model;
  }

  const modelPath = process.env.MODEL_PATH;
  console.log(`Loading model from ${modelPath}...`);

  // 📌 Load the model (example using TensorFlow.js)
  // Replace this with your model loading logic
  model = await tf.loadLayersModel(modelPath);
  console.log('Model loaded successfully.');
  return model;
}

// 📌 Main Lambda handler
exports.main = async (event) {
  try {
    // 📌 Load the model if not already loaded
    const loadedModel = await loadModel();

    // 📌 Parse the incoming request
    const body = JSON.parse(event.body);
    const input = body.input;

    // 📌 Convert input to a tensor (example for a simple model)
    const inputTensor = tf.tensor(input, [1, input.length]);

    // 📌 Run inference
    const prediction = await loadedModel.predict(inputTensor);
    const result = prediction.dataSync();

    // 📌 Clean up
    inputTensor.dispose();
    prediction.dispose();

    // 📌 Return the result
    return {
      statusCode: 200,
      body: JSON.stringify({ result }),
    };
  } catch (error) {
    console.error('Error during prediction:', error);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: 'Internal Server Error' }),
    };
  }
};
